result:
.model_top{
  display: flex;
  justify-content: space-between;
  &_right{
    display: flex
  }
}
.model_content{
  .level_box{
    .level_name{
      font-size: 14px;
      margin-bottom: 5px
    }
  }
  .model_card{
    background-color: #edeef3;
    min-height: 60px;
    box-shadow: 0 2px 4px rgba(0, 0, 0, .12), 0 0 6px rgba(0, 0, 0, .04);
    border-radius: 5px;
    padding: 10px;
    display: flex;
    cursor: pointer;
    align-items: center;
    .icon{
      font-size: 24px;
      margin-right: 20px;
    }
    .ci_name{
      font-size: 14px;
    }
  }
}
.form_detail{
  // width: calc(100% - 40px);
  width: 0px;
  height: calc(100% - 40px);
  position: absolute;
  top: 20px;
  left: 20px;
  transition: all 0.5s;
  background: #fff;
  overflow: hidden;
}
